#include <fstream>
#include <cstdio>
#include <locale>
#include <cassert>
#include <type_traits>
#include <utility>
#include <string>
#include <filesystem>
#include <chrono>
struct TemporaryFile {
    std::string name = (std::filesystem::temp_directory_path() /
        ("cpp-library-example-" +
            std::to_string(
                std::chrono::steady_clock::now().time_since_epoch().count())))
                           .string();
    ~TemporaryFile() { std::remove(name.c_str()); }
} file;
int main() {
    const char *filename = file.name.c_str();
    {
        std::ofstream output;
        output.open(filename);
        assert(output.is_open());
        assert(output.rdbuf());
        output << "42";
        output.close();
        std::ofstream moved;
        moved = std::move(output);
    }
    {
        std::ifstream input;
        input.open(filename);
        assert(input.rdbuf());
        int value{};
        input >> value;
        assert(value == 42);
        input.close();
        std::ifstream moved;
        moved = std::move(input);
    }
    {
        std::fstream stream{filename};
        assert(stream.rdbuf());
        std::fstream moved;
        moved = std::move(stream);
    }
    {
        std::filebuf buffer;
        buffer.pubimbue(std::locale::classic());
        assert(buffer.open(filename, std::ios::in | std::ios::out));
        assert(buffer.sbumpc() == '4');
        assert(buffer.sputbackc('4') == '4');
        buffer.pubseekpos(0, std::ios::out);
        buffer.sputc('7');
        assert(buffer.pubsync() == 0);
        std::filebuf other;
        std::swap(buffer, other);
        assert(other.close());
    }
}
